select json_agg(json_build_object(
 'item', ci.content_key, 'version', v.version_num, 'topic', c.topic_code, 'skill', c.skill_code,
 'brief_key', case when s.subject_key='biology' then 'ap_biology' else 'ap_statistics' end,
 'explainer', (select json_build_object('core_idea',e.core_idea,'understand',e.what_students_need_to_understand,'points',e.how_this_becomes_points,'answer_move',e.answer_move,'common_point_loss',e.common_point_loss,'weak_answer',e.weak_answer,'point_attaining_answer',e.point_attaining_answer)
   from app.topic_explainers e where e.subject_key=(case when s.subject_key='biology' then 'ap_biology' else 'ap_statistics' end) and e.topic_code=c.topic_code and e.status='published' limit 1),
 'brief', (select json_build_object('what_it_is',b.what_it_is,'why_it_matters',b.why_it_matters,'earned',b.how_points_are_earned,'answer_move',b.answer_move,'common_point_loss',b.common_point_loss)
   from app.topic_point_briefs b where b.subject_key=(case when s.subject_key='biology' then 'ap_biology' else 'ap_statistics' end) and b.topic_code=c.topic_code and b.status='published' limit 1)
)) as items
from k join app.content_items ci on ci.content_key=k.content_key
join app.exam_pack_versions epv on epv.id=ci.exam_pack_version_id and epv.retired_at is null
join app.exam_packs ep on ep.id=epv.exam_pack_id
join app.subjects s on s.id=ep.subject_id
join app.content_item_versions v on v.content_item_id=ci.id and v.status='published'
join app.content_item_cells c on c.content_item_version_id=v.id and c.is_primary and c.superseded_by is null;
